S=[]
def clean(s):return str(s).replace('—','-').replace('–','-').replace('\u2011','-').replace('\u2212','-')
def p(s,style='BodyText'):S.append(Paragraph(clean(s),styles[style]))
def h(s):p(s,'Heading2')
def page(title):
 if S:S.append(PageBreak())
 p(title,'Heading1')
def fmt(n):return '-' if n is None else f'{int(n):,}'.replace(',','.')
def dec(n,k=3):return '-' if n is None else f'{n:.{k}f}'.replace('.',',')
def load(n):return json.loads((ROOT/'output'/(n+'.json')).read_text())
def table(headers,rows,widths=None):
 data=[[Paragraph(html.escape(clean(x)),styles['HeaderCustom']) for x in headers]]+[[Paragraph(html.escape(clean(x)),styles['CellCustom']) for x in r] for r in rows]
 t=Table(data,colWidths=widths or [491/len(headers)]*len(headers),repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#214d66')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f0f5f7')]),('LINEBELOW',(0,0),(-1,0),.5,colors.white)]));S.append(t);S.append(Spacer(1,10))
def fig(name,caption,maxheight=425):
 file=ROOT/'output/figures'/(name+'.png')
 if not file.exists():raise FileNotFoundError(file)
 w,h0=ImageReader(str(file)).getSize();scale=min(491/w,maxheight/h0);S.append(KeepTogether([Image(str(file),width=w*scale,height=h0*scale,hAlign='LEFT'),Paragraph(clean(caption),styles['SmallNote'])]))
def footer(canvas,doc):
 canvas.saveState();canvas.setStrokeColor(colors.HexColor('#cbd9e1'));canvas.line(52,43,543,43);canvas.setFont('DV',7);canvas.setFillColor(colors.HexColor('#526b7c'));canvas.drawString(52,30,'Presidente 2026 | Análise de BU, logs e acesso | Dados oficiais TSE');canvas.drawRightString(543,30,str(doc.page));canvas.restoreState()
def run():
 audit=load('final-audit');assert audit['passed'],'Auditoria integral não aprovada'
