 t=load('timing-summary');op=load('operations-summary');sc=load('isonomy-scenarios');hy=load('hypothesis-checks');soc=load('social-context');an=load('anomalies');c17=load('1700-correlations');c35=load('correlations');bounds=load('1700-candidate-time-bounds');bound35=load('candidate-time-bounds')
 p('PRESIDENTE 2026','SmallNote');p('Horários, biometria<br/>e oportunidade de votar','Title');S.append(Spacer(1,20));p('Segundo turno, com comparação integral ao primeiro turno.','Heading2')
 p('Relatório analítico baseado nos arquivos oficiais publicados pelo TSE. Recontagem própria dos boletins, eventos de cinco em cinco minutos, comparação entre estados e seções, revisão de ocorrências e cenários condicionais de acesso.')
 p('Fechamento analítico: '+datetime.now().strftime('%d/%m/%Y %H:%M')+' - horário local de Brasília. Os números descrevem o corpus preservado nesta análise, com universo e exclusões explícitos.','SmallNote')
 table(['Universo publicado','Recontagem do 2º turno','Perfis nos dois turnos'],[[fmt(audit['raw_published_sections'])+' seções',fmt(audit['recount']['total'])+' votos',fmt(2*audit['raw_published_sections'])+' perfis de seção']])
 p('<b>Achado central.</b> A soma própria dos BUs coincide com os totais nacionais usados como referência. O conjunto temporal estrito tem '+fmt(a['timed']['sections'])+' seções domésticas. Nele, há '+fmt(a['timed']['post'])+' confirmações presidenciais após 17h e '+fmt(b['timed']['post'])+' após 17h05.')
 p('<b>Limite fundamental.</b> O horário do voto não revela o candidato. BUs e logs permitem limites matemáticos, mas não uma tabela exata de candidato por minuto. Da mesma forma, o horário de fechamento não mede a chegada do eleitor nem identifica o efeito da prorrogação.')
 page('Como ler este relatório')
 table(['Bloco','Pergunta respondida'],[('1. Cobertura e recontagem','O que foi obtido, conferido e excluído?'),('2. Horário e território','Quando ocorreram confirmações e onde se concentraram?'),('3. Biometria e tempo','Como identificação, votação e ritmo variam?'),('4. Primeiro turno e encerramento','O que a comparação ajuda a entender sobre a operação?'),('5. Ocorrências e candidatos','Quais divergências existem e quais conclusões são demonstráveis?'),('6. Isonomia e consequências','Quais cenários são compatíveis com hipóteses explícitas?'),('Anexos','Método, fontes, verificação e acesso aos dados.')],[140,351])
 h('Três camadas de evidência')
 p('<b>Observado:</b> somas dos BUs, mensagens de log, horários registrados, distribuições, correlações e dados cadastrais. <b>Inferência limitada:</b> explicação de um caso quando a sequência de registros sustenta a leitura, sem atribuir causa não registrada. <b>Cenário:</b> participação, ritmo ou preferência assumidos para explorar resultados possíveis.')
 p('“Pós 17h” significa estritamente depois de 17:00:00. O segundo corte é estritamente depois de 17:05:00. Eventos exatamente nos limites são contados à parte. Os gráficos de cinco minutos usam [início, fim); portanto a caixa iniciada às 17h inclui o segundo exato 17:00:00.')
 p('Os horários domésticos são convertidos para Brasília conforme o fuso do município. Exterior entra na recontagem geral, mas não nos mapas nem nos cortes da extensão brasileira. Na consulta individual de seção do exterior, o relógio exibido é local.')
 page('1. Cobertura e recontagem própria')
 table(['Item','Quantidade'],[('Seções principais com BU/log publicados',fmt(audit['raw_published_sections'])),('Seções agregadas - sem segunda urna independente',fmt(b['aggregated_sections'])),('Principais sem auxiliar publicado no índice capturado',fmt(b['unpublished_principal_sections'])),('Seções no exterior, fora do corte de Brasília',fmt(b['sums']['exterior'])),('Seções temporais estritas no 2º turno',fmt(b['timed']['sections'])),('Auxiliares ainda Recebido após revalidação',fmt(b['sums']['provisional_sections'])),('Erros de processamento na auditoria integral','0')],[345,146])
 p('A cobertura é integral em relação às seções principais com arquivos publicados no índice preservado. Isso não transforma as seções sem arquivo publicado em registros analisados. Seções agregadas são ligadas às respectivas principais para evitar duplicação de urna.')
 table(['Categoria','Soma dos BUs','Referência nacional','Diferença'],[(label,fmt(audit['recount'][k]),fmt(audit['reference'][k]),fmt(audit['differences'][k])) for k,label in [('v13','13 - Lula'),('v22','22 - Flávio Bolsonaro'),('blank','Brancos'),('null','Nulos'),('total','Total')]], [160,111,111,109])
 p('A margem nominal é '+fmt(sc['baseline_margin_13_minus_22'])+' votos para o 13. A igualdade foi conferida por soma direta das quantidades de cada BU, incluindo brancos e nulos; não por reprodução da soma nacional no lugar da leitura dos boletins.')
 p('Uma segunda implementação de extração, nos perfis de sessões, foi comparada aos resumos centrais: '+fmt(audit['independent_profile_comparison']['pairs'])+' pares, '+fmt(audit['independent_profile_comparison']['different'])+' diferenças nos totais e candidatos. Os conjuntos de identificadores dos perfis e protocolos dos dois turnos também coincidem com o universo publicado.')
 page('2. Confirmações presidenciais por horário')
 fig('01-series','Fonte: BUs e logs oficiais do 2º turno; corpus doméstico estrito. Cada degrau soma confirmações presidenciais em cinco minutos, incluindo brancos, nulos e nulos por suspensão. O painel inferior amplia o final do dia.',430)
 table(['Período','Confirmações'],[('Antes de 17:00:00',fmt(b['margin']['before_17'])),('17:00:00 a 17:05:00, inclusive',fmt(b['margin']['window_17_to_1705'])),('Depois de 17:05:00',fmt(b['margin']['after_1705']))],[345,146])
 p('A grande maioria dos votos do corpus foi confirmada antes das 17h. Confirmação depois desse horário pode ocorrer no atendimento de fila já existente, após uma habilitação anterior ou durante a continuação da votação. Os logs não permitem separar essas causas para cada pessoa.')
 page('3. Distribuição territorial')
 fig('02-maps','Mais escuro indica mais confirmações após o corte. Cada painel tem sua própria escala linear; compare os valores nas barras de cor. Quantidades absolutas são influenciadas pelo tamanho do eleitorado.',390)
 p('A quantidade tardia mostra concentração observada de eventos, e não quantos eleitores receberam uma comunicação de extensão. A taxa por votos no mesmo corpus complementa o mapa e reduz o efeito puramente mecânico do tamanho do estado.')
 fig('03-state-rates','A comparação absoluta e por 10 mil votos usa o mesmo universo estrito de cada UF. O denominador é o total de votos das seções conciliadas, não a população estadual.',400)
