 table(['Horário declarado no BU','Seções'],[('Até 17:00:00',fmt(b['closing']['at_or_before_strict17'])),('Após 17:00:00 até 17:05:00',fmt(b['closing']['within_closing_margin'])),('Após 17:05:00',fmt(b['closing']['after_closing_margin'])),('Antes de 17h com comparecimento integral',fmt(b['closing']['early_full_turnout'])),('Antes de 17h sem comparecimento integral',fmt(b['closing']['early_without_full_turnout']))],[345,146])
 p('O treinamento da Justiça Eleitoral prevê encerramento ordinário a partir de 17h depois do atendimento da fila [F3]. A nota do TSE sobre a decisão do STF informa continuidade onde a votação ainda não havia sido encerrada às 17h [F4]. A hora de recebimento local dessa orientação não é observada nestes arquivos.')
 page('4b. Encerramentos declarados mais tardios')
 late_examples=load('latest-closing-examples')
 def tm(sec):return '-' if sec is None else f'{int(sec)//3600:02}:{int(sec)%3600//60:02}:{int(sec)%60:02}'
