 p('A comparação usa '+fmt(t['paired_sections'])+' seções com ao menos 30 sessões utilizáveis em cada turno. As correlações abaixo mantêm a unidade de análise na seção. Remover a média de UF reduz diferenças entre estados, mas não controla todas as causas possíveis.')
 table(['Relação por seção','Pearson','Spearman','Dentro da UF'],[(r['label'],dec(r['pearson']),dec(r['spearman']),dec(r['within_uf_pearson'])) for r in t['correlations']],[272,73,73,73])
